        {
          "proposicao": "O texto descreve o SGSO como estruturado em 17 práticas de gestão distribuídas em grupos, e situa a integridade mecânica como a prática mais diretamente relacionada à manutenção.",
          "trechos": [
            "E4446f0d07a2cef20:0:696"
          ],
          "condicoes": [
            "Descrição feita em trabalho técnico secundário sobre manutenção",
            "Referência ao SGSO no contexto de atividades do setor de petróleo"
          ],
          "limites": [
            "Fonte secundária, não substitui o texto normativo primário",
            "O trecho não detalha todas as 17 práticas nem seus critérios"
          ]
        },
        {
          "proposicao": "Segundo o texto, a prática de integridade mecânica busca que instalação, sistemas, estruturas e equipamentos passem por inspeções, testes e manutenções de forma planejada e controlada, com objetivo de buscar integridade mecânica e adequação ao uso.",
          "trechos": [
            "E4446f0d07a2cef20:0:696",
            "E4446f0d07a2cef20:696:1395"
          ],
          "condicoes": [
            "No contexto da prática de gestão nº 13 do SGSO"
          ],
          "limites": [
            "Formulação apresentada por fonte explicativa",
            "O trecho não informa métodos, periodicidades ou critérios quantitativos"
          ]
        },
        {
          "proposicao": "O texto atribui ao regulamento a exigência de que equipamentos e sistemas críticos de segurança operacional estejam cobertos por planos de inspeção, teste e manutenção, relacionando essa cobertura à articulação entre integridade mecânica e elementos críticos de segurança operacional.",
          "trechos": [
            "E4446f0d07a2cef20:696:1395"
          ],
          "condicoes": [
            "Referência ao item 13.3.4 conforme reproduzido pela fonte",
            "Aplicação aos equipamentos e sistemas críticos de segurança operacional"
          ],
          "limites": [
            "A fonte faz interpretação de aderência entre práticas de gestão",
            "Não explicita critérios de classificação dos elementos críticos"
          ]
        }
      ]
    },
