            "Eca07636313e6d698:695:1395",
            "Eca07636313e6d698:2093:2552"
          ],
          "condicoes": [
            "No processo descrito de gestão de dados de incidentes pelo regulador"
          ],
          "limites": [
            "Trata-se de afirmação de artigo técnico, não de regra normativa",
            "Marcadores numéricos apagados impedem recuperar identificação exata do regulamento citado"
          ]
        }
      ]
    },
