            "E8f019fe8fc649726:1392:2090"
          ],
          "condicoes": [
            "Comparação conceitual feita pelo autor entre dois regimes regulatórios"
          ],
          "limites": [
            "Referência a prática e órgão estrangeiros não cria requisito brasileiro por si só",
