            "E1520624e05a1d63b:1388:2085",
            "E1520624e05a1d63b:2085:2291"
          ],
          "condicoes": [
            "Auditorias internas de 2012 e 2014 no FPSO CDSM"
          ],
          "limites": [
            "Resultado restrito ao caso relatado",
            "O trecho disponível não apresenta o conjunto completo das não conformidades nem o tratamento dado a cada uma"
